    s+=`<path d="M${L.tx0-11} ${L.cb-6}l5 12M${L.tx0-6} ${L.cb-6}l5 12" style="stroke:var(--muted);stroke-width:1"/>`;
    for(let k=0;k<=8;k++){if(N&&k%2)continue;s+=T(X(k),L.cb+13,k+' h','t-xs t-mid')}
    s+=T(L.tx1,L.cb+13,'24 h','t-xs t-end');
